failures=0

check_file() {
  local path="$1"
  if [[ -f "$path" ]]; then
    printf 'PASS: file exists: %s\n' "$path"
  else
    printf 'FAIL: file missing: %s\n' "$path" >&2
    failures=$((failures + 1))
  fi
}

contains() {
  local description="$1"
  local path="$2"
  local needle="$3"
  if rg -q --fixed-strings -- "$needle" "$path"; then
    printf 'PASS: %s\n' "$description"
  else
    printf 'FAIL: %s\n' "$description" >&2
    printf '  missing in %s: %s\n' "$path" "$needle" >&2
    failures=$((failures + 1))
  fi
}

contains_regex() {
  local description="$1"
  local path="$2"
  local pattern="$3"
  if rg -q -- "$pattern" "$path"; then
    printf 'PASS: %s\n' "$description"
  else
    printf 'FAIL: %s\n' "$description" >&2
    printf '  missing pattern in %s: %s\n' "$path" "$pattern" >&2
    failures=$((failures + 1))
  fi
}

not_contains() {
  local description="$1"
  local path="$2"
  local needle="$3"
  if rg -q --fixed-strings -- "$needle" "$path"; then
    printf 'FAIL: %s\n' "$description" >&2
    printf '  forbidden in %s: %s\n' "$path" "$needle" >&2
    failures=$((failures + 1))
  else
    printf 'PASS: %s\n' "$description"
  fi
}

equals() {
  local description="$1"
  local actual="$2"
  local expected="$3"
  if [[ "$actual" == "$expected" ]]; then
    printf 'PASS: %s\n' "$description"
  else
    printf 'FAIL: %s\n' "$description" >&2
    printf '  expected: %s\n  actual: %s\n' "$expected" "${actual:-<empty>}" >&2
    failures=$((failures + 1))
  fi
}

first_line_equals() {
  local description="$1"
  local path="$2"
  local expected="$3"
  local actual
  actual="$(head -n 1 "$path" || true)"
  equals "$description" "$actual" "$expected"
}

table_value() {
  local path="$1"
  local label="$2"
  awk -F'|' -v label="$label" '
    NF >= 3 {
      key = $2
      value = $3
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", value)
      if (key == label) {
        print value
        exit
      }
    }
  ' "$path"
}

